#include <cstring>
#include <harp_c_app.h>
#include <harp_synchronizer.h>
#include <core_registers.h>
#include <reg_spec.h>
#include <reg_types.h>
#include <hardware/adc.h>
#include <pico/time.h>
#include <config.h>
#include <interface_hash.h> // Generated by CMake from device.yml.
#ifdef DEBUG
    #include <pico/stdlib.h> // for uart printing
    #include <cstdio> // for printf
#endif

// App register addresses (must match device.yml).
enum app_reg_address_t: uint8_t
{
    ADC_REG = HarpCore::APP_REG_START_ADDRESS, // 32
};

inline constexpr uint32_t SAMPLE_INTERVAL_US = 1'000'000 / SAMPLE_RATE_HZ;
// RP2040 ADC input for each register channel, in payload order.
inline constexpr uint8_t ADC_INPUTS[ADC_CHANNEL_COUNT] {ADC0_INPUT, ADC1_INPUT};

// Define register contents.
#pragma pack(push, 1)
struct app_regs_t
{
    volatile uint8_t adc[ADC_CHANNEL_COUNT]; // app register 32
} app_regs;
#pragma pack(pop)

uint64_t next_sample_time_us;

/**
 * \brief sample both ADC channels and update the ADC register.
 */
void sample_adc()
{
    for (uint8_t ch = 0; ch < ADC_CHANNEL_COUNT; ++ch)
    {
        adc_select_input(ADC_INPUTS[ch]);
        app_regs.adc[ch] = uint8_t(adc_read() >> 4); // Keep the top 8 of 12 bits.
    }
}

void read_adc_reg(uint8_t reg_address)
{
    sample_adc();
    if (!HarpCore::is_muted())
        HarpCore::send_harp_reply(READ, reg_address);
}

// Define register specs and read/write handlers.
RegSpec app_reg_specs[]
{
    RegSpec::U8Array(&app_regs.adc, ADC_CHANNEL_COUNT,
                     read_adc_reg, HarpCore::write_reg_error)
};
const size_t reg_count = sizeof(app_reg_specs) / sizeof(RegSpec);

void app_reset()
{
    memset((void*)&app_regs, 0, sizeof(app_regs));
    next_sample_time_us = time_us_64() + SAMPLE_INTERVAL_US;
}

void update_app_state()
{
    uint64_t now_us = time_us_64();
    if (now_us < next_sample_time_us)
        return;
    next_sample_time_us += SAMPLE_INTERVAL_US;
    // If we fell behind, resync rather than bursting catch-up samples.
    if (now_us >= next_sample_time_us)
        next_sample_time_us = now_us + SAMPLE_INTERVAL_US;
    // Timestamp at the moment of sampling.
    uint64_t harp_time_us = HarpCore::harp_time_us_64();
    sample_adc();
    if (HarpCore::events_enabled() && !HarpCore::is_muted())
        HarpCore::send_harp_reply(EVENT, ADC_REG, harp_time_us);
}

// Create Harp App.
HarpCApp& app = HarpCApp::init(HARP_DEVICE_ID,
                               semver_t{FW_VERSION_MAJOR, FW_VERSION_MINOR,
                                        FW_VERSION_PATCH},
                               semver_t{HW_VERSION_MAJOR, HW_VERSION_MINOR,
                                        HW_VERSION_PATCH},
                               HARP_DEVICE_NAME,
                               (const uint8_t*)GIT_HASH,
                               interface_hash,
                               app_reg_specs, reg_count,
                               update_app_state, app_reset);

// Core0 main.
int main()
{
    adc_init();
    adc_gpio_init(ADC0_PIN);
    adc_gpio_init(ADC1_PIN);
// Init Synchronizer.
    HarpSynchronizer::init(uart1, HARP_SYNC_RX_PIN);
    app.set_synchronizer(&HarpSynchronizer::instance());
    app_reset(); // core.pico only calls app_reset() on RESET_DEV writes.
#ifdef DEBUG
    stdio_uart_init_full(uart0, 921600, UART_TX_PIN, -1); // use uart0 tx only.
    printf("Hello, from PhotodiodeBoard!\r\n");
#endif
    while(true)
        app.run();
}
